mapper.select:
SELECT member.id, member.user_id, app_user.email, app_user.display_name, member.role, member.status, member.joined_at, app_user.last_login_at, member.created_at FROM organization_member member JOIN app_user ON app_user.id = member.user_id WHERE member.organization_id = #{organizationId}
AND ( lower(app_user.display_name) LIKE lower(concat('%', #{keyword}, '%')) OR lower(app_user.email) LIKE lower(concat('%', #{keyword}, '%')) )
AND member.role = #{role}
AND member.status = #{status}
ORDER BY CASE member.role WHEN 'OWNER' THEN 0 WHEN 'ADMIN' THEN 1 WHEN 'MANAGER' THEN 2 WHEN 'SALES' THEN 3 ELSE 4 END, member.created_at ASC

mapper.insert:
INSERT INTO app_user (
    id, email, display_name, auth_provider, auth_subject, status, locale, created_at, updated_at
) VALUES (
    #{userId}, #{email}, #{displayName}, 'LOCAL', #{authSubject}, 'ACTIVE', 'zh-CN', #{now}, #{now}
)

INSERT INTO organization_member (
    id, organization_id, user_id, role, status, permissions, joined_at, created_at, updated_at
) VALUES (
    #{memberId}, #{organizationId}, #{userId}, #{role}, 'ACTIVE', '[]'::jsonb, #{now}, #{now}, #{now}
)

mapper.update:
WITH updated_user AS (
    UPDATE app_user
    SET display_name = #{displayName},
        updated_at = #{now},
        version = version + 1
    WHERE id = (
        SELECT user_id
        FROM organization_member
        WHERE organization_id = #{organizationId}
          AND id = #{memberId}
    )
)
UPDATE organization_member
SET role = #{role},
    status = #{status},
    updated_at = #{now},
    version = version + 1
WHERE organization_id = #{organizationId}
  AND id = #{memberId}

UPDATE auth_session
SET revoked_at = #{now}
WHERE organization_id = #{organizationId}
  AND member_id = #{memberId}
  AND revoked_at IS NULL
